\begin{tabular}{llccc}
\toprule
\textbf{Strategy} & \textbf{Method} & \textbf{Rel-F1} & \textbf{Evi-F1 (joint)} & \textbf{EDCR} \\
\midrule
Joint generation & RSFT CED (s43) & 0.4601 & 0.3605 & 0.6542 \\
Joint generation & SFT baseline & 0.4049 & 0.3117 & 0.6982 \\
